#[allow(unused_variables)]
fn scene_98(
    app: &mut App,
    context: BuildContext,
    state: &crate::scene_state::SceneHandle,
) -> WidgetRef {
    let v = ui::Theme::of(app, context);
    IntrinsicHeight::new()
        .child(
            ui::ActionBar::new(vec![
                {
                    let control = ui::IconButton::new(
                        IconTheme::merge(
                            None,
                            IconThemeData::new().size(16.0),
                            ui::FluentIcon(crate::generated_glyphs::glyph("Copy20Regular"))
                                .into_widget(),
                        )
                        .into_widget(),
                    )
                    .size(ui::ControlSize::Tiny)
                    .variant(ui::ControlVariant::Plain)
                    .tint(ui::Tint::Neutral);
                    control.on_pressed(|_| {}).into_widget()
                },
                {
                    let mut control = ui::Toggle::new("")
                        .pressed(app.read(&state.values)["pinned"].as_bool().unwrap())
                        .on_changed({
                            let state = state.clone();
                            move |app, value| crate::scene_state::set(app, &state, "pinned", value)
                        });
                    control.child = Row::new()
                        .main_axis_size(MainAxisSize::Min)
                        .cross_axis_alignment(CrossAxisAlignment::Center)
                        .spacing(v.control_small_gap)
                        .children(vec![
                            IconTheme::merge(
                                None,
                                IconThemeData::new().size(16.0),
                                ui::FluentIcon(crate::generated_glyphs::glyph("Pin20Regular"))
                                    .into_widget(),
                            )
                            .into_widget(),
                        ])
                        .into_widget();
                    control.enabled = true;
                    control.size = ui::ControlSize::Tiny;
                    control.variant = ui::ControlVariant::Plain;
                    control.tint = ui::Tint::Neutral;
                    control.into_widget()
                },
                ui::Divider {
                    vertical: true,
                    muted: false,
                }
                .into_widget(),
                {
                    let control = ui::IconButton::new(
                        IconTheme::merge(
                            None,
                            IconThemeData::new().size(16.0),
                            ui::FluentIcon(crate::generated_glyphs::glyph("Delete20Regular"))
                                .into_widget(),
                        )
                        .into_widget(),
                    )
                    .size(ui::ControlSize::Tiny)
                    .variant(ui::ControlVariant::Plain)
                    .tint(ui::Tint::Danger);
                    control.on_pressed(|_| {}).into_widget()
                },
            ])
            .align(MainAxisAlignment::Start)
            .stretch(true)
            .into_widget(),
        )
        .into_widget()
}
